import http from 'k6/http';
import {check, sleep} from 'k6';
import {Rate, Counter, Trend} from 'k6/metrics';

/**
 * Atlas: reproducible, deliberately bounded baseline test.
 * No network traffic is generated by checking this file in.
 *
 * Run locally by default. Production runs require an explicit opt-in.
 * Focus on CDN vs functional dynamic backend separately.
 */
const TARGET=__ENV.TARGET||'http://127.0.0.1:8765';
const PROFILE=__ENV.PROFILE||'static';
const LEVEL=__ENV.LEVEL||'smoke';
const RUN_PROD=__ENV.ALLOW_PRODUCTION_LOAD==='YES_I_AUTHORIZE_ATLAS_TEST';
const prodOrigin='https://atlas-live-data-studio.vercel.app';
const isLocal=/^https?:\/\/(127\.0\.0\.1|localhost)(:\d+)?$/.test(TARGET);
if(!isLocal && !(TARGET===prodOrigin&&RUN_PROD)){
 throw Error('Safety gate: use localhost, or exact Atlas production origin with ALLOW_PRODUCTION_LOAD=YES_I_AUTHORIZE_ATLAS_TEST');
}
if(!['static','weather','train','rail'].includes(PROFILE))throw Error('Unknown PROFILE');
if(!['smoke','baseline','step'].includes(LEVEL))throw Error('Unknown LEVEL');
if(TARGET===prodOrigin && LEVEL==='step')throw Error('Step testing production is not enabled. Use an isolated preview with explicit approval.');
if(PROFILE!=='static'&&TARGET===prodOrigin&&!(__ENV.ALLOW_PROVIDER_TEST==='YES_I_ACCEPT_PROVIDER_CALLS')){
 throw Error('Provider routes can use real upstream quotas: ALLOW_PROVIDER_TEST must be explicitly enabled.');
}
// The load generator should never accidentally hammer the data providers.
// Single region fixed parameters; URLs are constant to test cache reuse.
const paths={
 static:'/',
 weather:'/api/immersive-weather?kind=forecast&lat=43.2965&lon=5.3698',
 train:'/api/train-map',
 rail:'/api/rail-lines?south=42.9&north=43.8&west=4.7&east=5.9',
};
const duration=LEVEL==='smoke'?'30s':LEVEL==='baseline'?'3m':'6m';
const rate=LEVEL==='smoke'?1:LEVEL==='baseline'?2:5;
const vus=LEVEL==='smoke'?2:LEVEL==='baseline'?5:12;
const errorRate=new Rate('atlas_response_error');
const cacheHit=new Counter('atlas_cache_hit');
const cacheMiss=new Counter('atlas_cache_miss');
const cacheStale=new Counter('atlas_cache_stale');
const cacheUnknown=new Counter('atlas_cache_unknown');
const servedBytes=new Counter('atlas_response_bytes');
const successfulDuration=new Trend('atlas_success_duration',true);
const dataAge=new Trend('atlas_age_seconds');
export const options={
 discardResponseBodies:true,
 noConnectionReuse:false,
 maxRedirects:0,
 scenarios:{
  fixed_rate:{
   executor:'constant-arrival-rate',
   rate,timeUnit:'1s',
   duration,
   preAllocatedVUs:vus,
   maxVUs:vus*2,
   exec:'probe',
   tags:{profile:PROFILE,level:LEVEL}
  }
 },
 thresholds:{
  http_req_failed:[{threshold:'rate<0.05',abortOnFail:true,delayAbortEval:'15s'}],
  atlas_response_error:[{threshold:'rate<0.05',abortOnFail:true,delayAbortEval:'15s'}],
  http_req_duration:['p(95)<3000'],
  dropped_iterations:['count<2']
 }
};
export function probe(){
 const started=Date.now();
 const response=http.get(TARGET+paths[PROFILE],{
  timeout:'8s',
  redirects:0,
  tags:{profile:PROFILE,level:LEVEL},
  headers:{Accept:PROFILE==='static'?'text/html':'application/json'},
  responseType:'none'
 });
 const ok=response.status===200;
 errorRate.add(!ok);
 check(response,{
  'HTTP 200 (no errors)':r=>r.status===200,
  'latency under eight seconds':r=>r.timings.duration<8000
 });
 if(ok)successfulDuration.add(response.timings.duration);
 const c=String(response.headers['X-Vercel-Cache']||response.headers['x-vercel-cache']||'').toUpperCase();
 if(c==='HIT')cacheHit.add(1);
 else if(c==='MISS')cacheMiss.add(1);
 else if(c==='STALE'||c==='PRERENDER')cacheStale.add(1);
 else cacheUnknown.add(1);
 const bytes=Number(response.headers['Content-Length']||response.headers['content-length']);
 if(Number.isFinite(bytes)&&bytes>=0)servedBytes.add(bytes);
 const age=Number(response.headers.Age||response.headers.age);
 if(Number.isFinite(age)&&age>=0)dataAge.add(age);
 // Arrival-rate executor schedules iterations; do not sleep() to regulate RPS.
}
export function handleSummary(data){
 return {
  stdout:JSON.stringify({
   tool:'k6',type:'atlas-load-baseline',target:TARGET,profile:PROFILE,level:LEVEL,
   thresholdPass:Object.values(data.metrics||{}).filter(v=>v.thresholds).every(m=>Object.values(m.thresholds).every(x=>x.ok)),
   metrics:data.metrics,
   note:'CDN HTTP observations only. Origin invocations and third-party calls must be correlated with Vercel metrics.'
  },null,2)+'\n',
  'monitoring/k6-results/latest.json':JSON.stringify(data,null,2)
 };
}
